    + `<g clip-path="url(#${id})"><image class="sm-${key}" data-sm="${name}-${key}" href="${done || ''}" x="${f(x0)}" y="${f(y0)}" width="${f(cols * bw)}" height="${f(rows * bh)}" preserveAspectRatio="none"/></g>`;
